/**
 * Adds a "Call with BrightHire" button next to any candidate phone
 * numbers found on the page.
 *
 * Greenhouse began rolling out a new candidate page design circa 01/24.
 * This content script works on the older version of the page, and
 * `greenhouseCandidateContentScriptV2` works on the newer version of the page.
 */

import { MutationSummary, type Summary } from "../../../utils/MutationSummary";
import { onDocumentLoaded } from "../../../utils/onDocumentLoaded";
import { isAtsCallButtonHidden } from "../../../utils/orgSettings";
import { phoneNumberRegex } from "../../../utils/regex";
import { initSentry } from "../../../utils/sentry";
import { buildUrl } from "../../../utils/url";
import { BRIGHTHIRE_ID, BUTTON_STYLE } from "../../style";
import { VersionManager } from "./VersionManager";

initSentry();

const versionManager = new VersionManager({ version: 1 });

const buildBrightHireButton = async (
  phoneNumber: string,
): Promise<HTMLButtonElement> => {
  const brighthireButton = document.createElement("button");
  brighthireButton.id = BRIGHTHIRE_ID;
  brighthireButton.setAttribute("style", BUTTON_STYLE);
  brighthireButton.innerText = "Call With BrightHire";
  const url = await buildUrl(
    "/interview-assistant/integrations/greenhouseCandidate",
    {
      url: window.location.href,
      phoneNumber,
    },
  );
  brighthireButton.onclick = () =>
    chrome.runtime.sendMessage({
      action: "openIA",
      payload: { url, windowAvailHeight: window.screen.availHeight },
    });
  return brighthireButton;
};

const insertBrightHireButton = async (element: Node): Promise<void> => {
  if (await isAtsCallButtonHidden()) return;
  /** We found a selector that matches the V1 page, tell other pages to shut down */
  versionManager.sendShutdown();

  const phoneNumber = phoneNumberRegex.exec(
    element.textContent?.replace(/[\W]/g, "") ?? "",
  )?.[0];
  const parent = element.parentNode;
  if (parent == null || phoneNumber == null) {
    return;
  }

  // avoid duplicate buttons
  document.querySelector(`#${BRIGHTHIRE_ID}`)?.remove();

  const brightHireButton = await buildBrightHireButton(phoneNumber);
  parent.insertBefore(brightHireButton, element.nextSibling);
};

const handleContactItemMutation = (summaries: Summary[]): void => {
  summaries.forEach((summary) => {
    summary.added.forEach((node) => {
      insertBrightHireButton(node);
    });
  });
};

const watch = (): void => {
  const summary = new MutationSummary({
    callback: handleContactItemMutation,
    queries: [{ element: ".contact-item" }],
  });
  document.querySelectorAll(".contact-item").forEach((e) => {
    insertBrightHireButton(e);
  });
  versionManager.listenForShutdown().then(() => {
    summary.disconnect();
  });
};

onDocumentLoaded(watch);
