import { addMessageListener, sendMessage } from "../../../utils/message";

type Version = 1 | 2;

type VersionManagerOptions = {
  /** The version of *this* content script */
  version: Version;
};

/**
 * Allows different content script versions to communicate about
 * which should be used.
 */
export class VersionManager {
  private readonly messageKey = "ghCandidateScriptVersion";

  private shutdownSent = false;

  private version: Version;

  constructor({ version }: VersionManagerOptions) {
    this.version = version;
  }

  /**
   * Returns a promise that resolves when a shutdown signal is
   * broadcast by another script version
   */
  listenForShutdown(): Promise<void> {
    return new Promise((resolve) => {
      addMessageListener(({ message: { action, payload } }) => {
        if (
          action === this.messageKey &&
          payload?.ghCandidateScriptVersion !== this.version
        ) {
          resolve();
        }
      });
    });
  }

  /**
   * Instructs other script versions to shutdown
   */
  sendShutdown(): void {
    if (this.shutdownSent) return;
    this.shutdownSent = true;
    sendMessage({
      action: this.messageKey,
      payload: { ghCandidateScriptVersion: this.version },
    });
  }
}
